<tr data-user-id="<?= (int)$u->id ?>" data-username="<?= Ui::h($u->username) ?>"><td><div class="employee-list-person"><div><b><?= Ui::h($u->name) ?></b><small><?= Ui::h($u->username) ?></small></div></div></td><td><?= Ui::h($chain['university']??'Yo‘q') ?></td><td><?= Ui::h($chain['faculty']??'Yo‘q') ?></td><td><?= Ui::h($chain['department']??'Yo‘q') ?></td><td><?= Ui::h($chain['unit']??'Yo‘q') ?></td><td><?= Ui::h(User::ROLES[$u->role]??'Yo‘q') ?><small><?= Ui::h(Catalog::CATEGORIES[$u->category]??'Yo‘q') ?></small></td><td><span class="badge <?= $u->active?'approved':'rejected' ?>"><?= $u->active?'Faol':'Nofaol / bloklangan' ?></span></td><td><?php if($super || !$u->isAdmin()): ?><?= Html::a('Tahrirlash',['admin/user-edit','id'=>$u->id],['class'=>'button small secondary']) ?><?php else: ?><span class="muted">Faqat superadministrator</span><?php endif ?></td></tr>
<?php endforeach ?></tbody></table></div><?php endif ?></section>

